begin;
create extension if not exists pgtap with schema extensions;
select plan(10);

select ok((select not rolcanlogin and not rolbypassrls from pg_catalog.pg_roles where rolname='offline_pos_writer'),'offline writer is non-login and does not bypass RLS');
select is((select count(*) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_roles r on r.oid=p.proowner where n.nspname='offline_pos_private' and p.prosecdef and p.proconfig @> array['search_path=""'] and r.rolname='offline_pos_writer'),7::bigint,'all seven offline business functions are hardened and writer-owned');
select ok((select bool_and(relrowsecurity and not relforcerowsecurity) from pg_catalog.pg_class where oid in ('public.offline_pos_policies'::regclass,'public.device_credentials'::regclass,'public.offline_device_management_commands'::regclass,'public.offline_grants'::regclass,'public.offline_sale_ingestions'::regclass,'public.offline_reconciliations'::regclass,'public.offline_reconciliation_events'::regclass,'public.offline_attendance_ingestions'::regclass)),'all offline tables enable non-forced RLS');
select is((select count(*) from pg_catalog.pg_policies where schemaname='public' and tablename in ('offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions') and roles && array['anon','authenticated']::name[]),0::bigint,'offline tables have no client policies');
select ok((select bool_and(not has_table_privilege('anon',format('public.%I',name),'SELECT') and not has_table_privilege('authenticated',format('public.%I',name),'SELECT')) from unnest(array['offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions']) name),'client roles cannot read offline authority or events');
select ok((select bool_and(has_table_privilege('service_role',format('public.%I',name),'SELECT')) from unnest(array['offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions']) name),'service role may read repository tables');
select ok((select bool_and(not has_table_privilege('service_role',format('public.%I',name),'INSERT') and not has_table_privilege('service_role',format('public.%I',name),'UPDATE') and not has_table_privilege('service_role',format('public.%I',name),'DELETE')) from unnest(array['device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions']) name),'service role cannot mutate offline records directly');
select ok((select bool_and(has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('public',p.oid,'EXECUTE')) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='offline_pos_private' and p.proname<>'forbid_immutable_mutation'),'only service role can call offline business functions');
select ok((select not has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('public',p.oid,'EXECUTE') from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='offline_pos_private' and p.proname='forbid_immutable_mutation'),'trigger helper is not externally executable');
select ok((select count(*)=5 from pg_catalog.pg_constraint where conname in ('offline_grants_device_fk','offline_grants_register_branch_fk','offline_grants_location_fk','offline_grants_operator_fk','offline_sale_ingestions_credential_fk')),'tenant-safe composite foreign keys protect grant and ingestion bindings');
select * from finish();
rollback;
